    rec={'reviewer':'A094/fleet05/B19','at':stamp,'verdict':'HOLDS_AT_FULL_STATED_SCOPE' if full else 'HOLDS_AT_EXPLICIT_DEPENDENCY_CLAUSES_ONLY','scope':scope,'method':'Independent complete signed Fourier/physical edge/entropy-sector/KL reconstruction; own exact checker and outward rational certificates, no author checker imported','proof':str(RUN/'AUDIT.md'),'validation':str(RUN/'out/EXACT_RESULTS.json'),'source_claims_path':str(path),'source_claims_sha256':sha(path),'substantive_repair_supplied':False,'contributor_conflict':False,'declared_statement_sha256':c['statement_sha256'],'plain_statement_sha256':plain,'canonical_statement_hypotheses_sha256':canon,'known_hash_form_match':c['statement_sha256'] in [plain,canon]}
    assert rec['known_hash_form_match']
    c['review_records'].append(rec);c['status']='INDEPENDENTLY_RECONSTRUCTED_AT_FULL_STATED_SCOPE_LOCALLY' if full else 'PARTIALLY_RECONSTRUCTED_AT_EXPLICIT_DEPENDENCY_SCOPE_LOCALLY'
    claims.append(c);hashes.append(rec)
